import json
import datetime as dt
import urllib.request

START = dt.datetime(2024, 12, 1, 0, 0, 0, tzinfo=dt.timezone.utc)
END = dt.datetime(2024, 12, 31, 23, 59, 59, tzinfo=dt.timezone.utc)

BASE = "https://api.github.com/repos/cli/cli"


def parse_ts(s: str) -> dt.datetime:
    # GitHub timestamps like 2024-12-31T23:59:59Z
    return dt.datetime.fromisoformat(s.replace("Z", "+00:00"))


def fetch_json(url: str):
    req = urllib.request.Request(url, headers={"User-Agent": "codex-cli"})
    with urllib.request.urlopen(req) as resp:
        data = resp.read().decode("utf-8")
        return json.loads(data)


def fetch_pulls_created_in_range():
    page = 1
    pulls = []
    while True:
        url = f"{BASE}/pulls?state=all&sort=created&direction=desc&per_page=100&page={page}"
        data = fetch_json(url)
        if not data:
            break
        for pr in data:
            created = parse_ts(pr["created_at"])
            if created < START:
                return pulls
            if START <= created <= END:
                pulls.append(pr)
        last_created = parse_ts(data[-1]["created_at"])
        if last_created < START:
            break
        page += 1
    return pulls


def fetch_issues_created_in_range():
    page = 1
    issues = []
    while True:
        url = f"{BASE}/issues?state=all&sort=created&direction=desc&per_page=100&page={page}"
        data = fetch_json(url)
        if not data:
            break
        for issue in data:
            # Skip pull requests in issues list
            if "pull_request" in issue:
                continue
            created = parse_ts(issue["created_at"])
            if created < START:
                return issues
            if START <= created <= END:
                issues.append(issue)
        # Use last item's created_at, even if it's a PR, to decide when to stop.
        last_created = parse_ts(data[-1]["created_at"])
        if last_created < START:
            break
        page += 1
    return issues


pulls = fetch_pulls_created_in_range()

pr_total = len(pulls)
pr_merged = sum(1 for pr in pulls if pr.get("merged_at"))
pr_closed = sum(1 for pr in pulls if pr.get("state") == "closed")

merge_days = []
for pr in pulls:
    merged_at = pr.get("merged_at")
    if merged_at:
        created = parse_ts(pr["created_at"])
        merged = parse_ts(merged_at)
        delta_days = (merged - created).total_seconds() / 86400
        merge_days.append(delta_days)

if merge_days:
    avg_merge_days = round(sum(merge_days) / len(merge_days), 1)
else:
    avg_merge_days = 0.0

from collections import Counter
contributors = Counter()
for pr in pulls:
    user = pr.get("user") or {}
    login = user.get("login") or ""
    if login:
        contributors[login] += 1

if contributors:
    top_contributor = contributors.most_common(1)[0][0]
else:
    top_contributor = ""

issues = fetch_issues_created_in_range()
issue_total = len(issues)

bug_issues = []
for issue in issues:
    labels = issue.get("labels", [])
    has_bug = False
    for label in labels:
        name = label.get("name", "")
        if "bug" in name.lower():
            has_bug = True
            break
    if has_bug:
        bug_issues.append(issue)

issue_bug = len(bug_issues)

resolved_bugs = 0
for issue in bug_issues:
    closed_at = issue.get("closed_at")
    if not closed_at:
        continue
    closed = parse_ts(closed_at)
    if START <= closed <= END:
        resolved_bugs += 1

report = {
    "pr": {
        "total": pr_total,
        "merged": pr_merged,
        "closed": pr_closed,
        "avg_merge_days": avg_merge_days,
        "top_contributor": top_contributor,
    },
    "issue": {
        "total": issue_total,
        "bug": issue_bug,
        "resolved_bugs": resolved_bugs,
    },
}

with open("/app/report.json", "w", encoding="utf-8") as f:
    json.dump(report, f, indent=2)

print(json.dumps(report, indent=2))
PY"}

